# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ONDALIK İFADELERİN KAREKÖKLERİNİ BELİRLEME (M.8.1.3.7)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">3 Adımda Ondalık Karekök Alma</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">1. Adım: Ondalık ifadeyi rasyonel kesir olarak yaz</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" fill="#334155">0,36 = 36 / 100   |   1,44 = 144 / 100</text>\n  <text x="180" y="144" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">2. Adım: Payın ve paydanın ayrı ayrı karekökünü al</text>\n  <text x="180" y="166" text-anchor="middle" font-size="11" fill="#334155">kök(36 / 100) = kök(36) / kök(100) = 6 / 10</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">3. Adım: Sonucu tekrar ondalık gösterime çevir</text>\n  <text x="180" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">6 / 10 = 0,6   ve   12 / 10 = 1,2</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Basamak Sayısı Kuralı ve Örnekler</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• kök(0,09) = kök(9 / 100) = 3 / 10 = 0,3</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• kök(2,25) = kök(225 / 100) = 15 / 10 = 1,5</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• kök(0,0121) = kök(121 / 10000) = 11 / 100 = 0,11</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">DİKKAT: kök(0,9) ≠ 0,3 ! Çünkü 0,9 = 9 / 10 olup</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">paydadaki 10 sayısı tam kare değildir!</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#166534">Virgülden sonra 2 basamak ➔ dışarıda 1 basamak olur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">RASYONEL (Q) VE İRRASYONEL (I) SAYILAR KÜMESİ (M.8.1.3.8)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Rasyonel Sayılar (Q) — a / b (b ≠ 0)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">1. Doğal Sayılar (N) ve Tam Sayılar (Z):</text>\n  <text x="180" y="112" text-anchor="middle" font-size="11" fill="#334155">0, 5, -12, 24 (Paydası 1 olan kesirlerdir)</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">2. Kesirler ve Sonlu Ondalık Gösterimler:</text>\n  <text x="180" y="154" text-anchor="middle" font-size="11" fill="#334155">3 / 4, -7 / 5, 0,25, 1,8</text>\n  <text x="180" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">3. Devirli Ondalık Gösterimler:</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11" fill="#334155">0,333... = 1 / 3  |  1,2727... = 14 / 11</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">4. Tam Karelerin Karekökü: kök(49) = 7, kök(0,64) = 0,8</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">İrrasyonel Sayılar (I) — a / b Yazılamayanlar</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">1. Tam Kare Olmayan Sayıların Karekökleri:</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#334155">kök(2), kök(3), kök(5), -kök(10), kök(0,9)</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">2. Pi (π) Sayısı:</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11" fill="#334155">π = 3,14159265... (Düzensiz ve sonsuz devam eder)</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">3. Düzensiz Sonsuz Ondalık Gösterimler:</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" fill="#334155">2,1010010001... (Devretmeyen sonsuz açılımlar)</text>\n  <text x="520" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#881337">Not: 3, 3,14 ve 22/7 değerleri π\'nin yaklaşık değeridir!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GERÇEK (REEL) SAYILAR KÜMESİ ŞEMASI: R = Q ∪ I</text>\n  <rect x="25" y="45" width="650" height="195" rx="10" fill="#f1f5f9" stroke="#334155" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">GERÇEK (REEL) SAYILAR (R) — Sayı Doğrusundaki Tüm Noktalar</text>\n\n  <rect x="45" y="80" width="380" height="145" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="235" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Rasyonel Sayılar (Q): 3/5, -0,4, 1,222..., kök(1,44)</text>\n\n  <rect x="75" y="112" width="320" height="100" rx="8" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="235" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Tam Sayılar (Z): ... -3, -2, -1, -kök(25)</text>\n\n  <rect x="115" y="144" width="240" height="56" rx="8" fill="#93c5fd" stroke="#1e40af" stroke-width="1.5"/>\n  <text x="235" y="166" text-anchor="middle" font-size="12" font-weight="bold" fill="#172554">Doğal Sayılar (N): 0, 1, 2, kök(16)</text>\n  <text x="235" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">Alt küme zinciri: N ⊂ Z ⊂ Q ⊂ R</text>\n\n  <rect x="445" y="80" width="210" height="145" rx="8" fill="#ffe4e6" stroke="#e11d48" stroke-width="1.5"/>\n  <text x="550" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">İrrasyonel Sayılar (I)</text>\n  <text x="550" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">kök(2), kök(7), -kök(12)</text>\n  <text x="550" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">π (Pi sayısı)</text>\n  <text x="550" y="184" text-anchor="middle" font-size="11" fill="#881337">0,121221222...</text>\n  <text x="550" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Q ∩ I = ∅ (Ayrık kümeler)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
